const sources = [
  {
    source: 'Kanata North BA',
    actorInput: {
      runMode: 'PRODUCTION',
      startUrls: [{ url: 'https://www.kanatanorthba.com/member-directory/' }],
      respectRobotsTxtFile: true,
      linkSelector: '',
      globs: [],
      pseudoUrls: [],
      excludes: [],
      pageFunction: "
async function pageFunction(context) {
    const clean = (v) => (v || '').replace(/\s+/g, ' ').trim();
    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

    // Expand the directory. Stop when the button disappears or no longer changes the page.
    for (let i = 0; i < 40; i++) {
        const button = [...document.querySelectorAll('button, a')]
            .find((el) => /load more/i.test(clean(el.textContent)) && !el.disabled);
        if (!button) break;
        const before = document.body.innerText.length;
        button.click();
        await sleep(1200);
        if (document.body.innerText.length <= before) break;
    }

    const records = [];
    for (const heading of [...document.querySelectorAll('h2')]) {
        const organization = clean(heading.textContent);
        if (!organization || /questions|kanata north ba/i.test(organization)) continue;

        let card = heading;
        for (let i = 0; i < 8 && card; i++, card = card.parentElement) {
            const t = clean(card.innerText);
            if (/Location:/i.test(t) && (/Website:|Phone:|Email:/i.test(t))) break;
        }
        if (!card) continue;

        const text = clean(card.innerText);
        const website = [...card.querySelectorAll('a[href]')]
            .map((a) => a.href)
            .find((href) =>
                /^https?:/i.test(href) &&
                !/kanatanorthba\.com|google\.com|mailto:|tel:/i.test(href)
            ) || '';

        const profileUrl = [...card.querySelectorAll('a[href]')]
            .map((a) => ({ href: a.href, text: clean(a.textContent) }))
            .find((a) => /learn more/i.test(a.text))?.href || context.request.url;

        const email = (text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) || [''])[0];
        const phone = (text.match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/) || [''])[0];
        const address = clean((text.match(/Location:\s*(.*?)(?:Website:|Phone:|Email:|$)/i) || ['', ''])[1]);
        const paragraphs = [...card.querySelectorAll('p')].map((p) => clean(p.textContent)).filter(Boolean);
        const description = paragraphs.sort((a, b) => b.length - a.length)[0] || '';

        records.push({
            source: 'Kanata North BA',
            organization,
            website,
            publicPhone: phone,
            generalEmail: email,
            address,
            description,
            profileUrl,
            sourcePageUrl: context.request.url,
            dateScraped: new Date().toISOString()
        });
    }
    return records;
}
",
      injectJQuery: false,
      proxyConfiguration: { useApifyProxy: true },
      headless: true,
      downloadMedia: false,
      downloadCss: false,
      maxPagesPerCrawl: 1,
      maxRequestRetries: 2,
      waitUntil: ['networkidle2']
    }
  },
  {
    source: 'Invest Ottawa',
    actorInput: {
      runMode: 'PRODUCTION',
      startUrls: [{ url: 'https://techjobfinder.investottawa.ca/companies' }],
      respectRobotsTxtFile: true,
      linkSelector: '',
      globs: [],
      pseudoUrls: [],
      excludes: [],
      pageFunction: "
async function pageFunction(context) {
    const clean = (v) => (v || '').replace(/\s+/g, ' ').trim();
    await new Promise((resolve) => setTimeout(resolve, 2500));

    const links = [...document.querySelectorAll('a[href]')]
        .filter((a) => /\/companies\//i.test(a.href))
        .filter((a, i, arr) => arr.findIndex((b) => b.href === a.href) === i);

    const records = [];
    for (const link of links) {
        let card = link.closest('article, li, [class*="company"], [class*="card"]') || link.parentElement;
        for (let i = 0; i < 5 && card && clean(card.innerText).length < 40; i++) card = card.parentElement;
        const text = clean((card || link).innerText);
        if (!text) continue;

        const heading = (card || link).querySelector('h1,h2,h3,h4,h5,h6');
        let organization = clean(heading?.textContent);
        if (!organization) {
            organization = clean(link.textContent)
                .replace(/\b\d+\s+jobs?\b/ig, '')
                .replace(/\bview company\b/ig, '')
                .trim();
        }
        if (!organization || /explore companies|search jobs|talent network/i.test(organization)) continue;

        const description = text
            .replace(organization, '')
            .replace(/\b\d+\s+jobs?\b/ig, '')
            .replace(/\bview company\b/ig, '')
            .trim();

        records.push({
            source: 'Invest Ottawa',
            organization,
            website: '',
            publicPhone: '',
            generalEmail: '',
            address: 'Ottawa, Ontario',
            description,
            profileUrl: link.href,
            sourcePageUrl: context.request.url,
            dateScraped: new Date().toISOString()
        });
    }
    return records;
}
",
      injectJQuery: false,
      proxyConfiguration: { useApifyProxy: true },
      headless: true,
      downloadMedia: false,
      downloadCss: false,
      maxPagesPerCrawl: 1,
      maxRequestRetries: 2,
      waitUntil: ['networkidle2']
    }
  },
  {
    source: 'Ottawa Board of Trade',
    actorInput: {
      runMode: 'PRODUCTION',
      startUrls: [{ url: 'https://business.ottawabot.ca/list/ql/technology-14.htm' }],
      respectRobotsTxtFile: true,
      linkSelector: '',
      globs: [],
      pseudoUrls: [],
      excludes: [],
      pageFunction: "
async function pageFunction(context) {
    const clean = (v) => (v || '').replace(/\s+/g, ' ').trim();
    const records = [];
    const headings = [...document.querySelectorAll('h3,h4,h5')];

    for (const heading of headings) {
        const organization = clean(heading.textContent);
        if (!organization || /technology|ottawa board of trade|business directory/i.test(organization)) continue;

        let card = heading;
        for (let i = 0; i < 7 && card; i++, card = card.parentElement) {
            const t = clean(card.innerText);
            if (t.length > organization.length + 15 && (/\d{3}[-\s)]\d{3}[-\s]\d{4}/.test(t) || / ON /i.test(t))) break;
        }
        if (!card) continue;

        const text = clean(card.innerText);
        const phone = (text.match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/) || [''])[0];
        const addressLink = [...card.querySelectorAll('a[href*="google.com"]')][0];
        const profileLink = [...card.querySelectorAll('a[href]')]
            .find((a) => clean(a.textContent) === organization || clean(a.textContent).includes(organization));
        const externalWebsite = [...card.querySelectorAll('a[href]')]
            .map((a) => a.href)
            .find((href) =>
                /^https?:/i.test(href) &&
                !/ottawabot\.ca|chambermaster\.com|google\.com/i.test(href)
            ) || '';
        const paragraphs = [...card.querySelectorAll('p')].map((p) => clean(p.textContent)).filter(Boolean);
        const description = paragraphs.sort((a, b) => b.length - a.length)[0] || '';

        records.push({
            source: 'Ottawa Board of Trade',
            organization,
            website: externalWebsite,
            publicPhone: phone,
            generalEmail: '',
            address: clean(addressLink?.textContent),
            description,
            profileUrl: profileLink?.href || context.request.url,
            sourcePageUrl: context.request.url,
            dateScraped: new Date().toISOString()
        });
    }
    return records;
}
",
      injectJQuery: false,
      proxyConfiguration: { useApifyProxy: true },
      headless: true,
      downloadMedia: false,
      downloadCss: false,
      maxPagesPerCrawl: 1,
      maxRequestRetries: 2,
      waitUntil: ['networkidle2']
    }
  }
];
return sources.map((s) => ({ json: s }));

const input = $input.all();
const flattened = [];

for (const item of input) {
  const payload = item.json?.body ?? item.json;
  const records = Array.isArray(payload) ? payload : [payload];
  for (const record of records) {
    if (!record || !record.organization) continue;
    flattened.push(record);
  }
}

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const normalizeOrg = (v) => clean(v)
  .toLowerCase()
  .replace(/\b(incorporated|corporation|company|limited|inc|ltd|corp|co)\b\.?/g, '')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

const domainFromUrl = (value) => {
  if (!value) return '';
  try {
    const u = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`);
    return u.hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return '';
  }
};

const techRules = [
  ['AI & Data', /\b(ai|artificial intelligence|machine learning|data science|data analytics|analytics|computer vision|natural language|nlp)\b/i],
  ['Cybersecurity', /\b(cyber|cybersecurity|information security|network security|identity|zero trust|security software)\b/i],
  ['Cloud & DevOps', /\b(cloud|devops|infrastructure|platform engineering|managed cloud|kubernetes|hosting)\b/i],
  ['Telecom & Networking', /\b(telecom|telecommunications|networking|network equipment|5g|wireless|optical network)\b/i],
  ['Semiconductors & Photonics', /\b(semiconductor|photonics|microelectronics|chip|silicon|optical)\b/i],
  ['Robotics / Hardware / IoT', /\b(robot|robotics|autonomous|hardware|internet of things|iot|embedded|sensor|electronics)\b/i],
  ['Fintech', /\b(fintech|financial technology|payments|banking software|insurance technology)\b/i],
  ['Digital Health', /\b(digital health|healthtech|medical technology|medtech|health software)\b/i],
  ['Clean Technology', /\b(cleantech|clean technology|renewable|energy technology|climate technology)\b/i],
  ['IT Services / Consulting', /\b(it services|technology consulting|digital transformation|managed services|systems integrator|software consulting)\b/i],
  ['Software / SaaS', /\b(software|saas|platform|application|app development|developer tools|web technology|enterprise applications)\b/i],
];

return flattened.map((record) => {
  const source = clean(record.source);
  const organization = clean(record.organization);
  const website = clean(record.website);
  const description = clean(record.description);
  const address = clean(record.address);
  const text = `${organization} ${description} ${website}`;
  let techCategory = 'Other Technology';
  let techMatch = source === 'Invest Ottawa' || source === 'Ottawa Board of Trade';

  for (const [category, regex] of techRules) {
    if (regex.test(text)) {
      techCategory = category;
      techMatch = true;
      break;
    }
  }

  const domain = domainFromUrl(website);
  const dedupKey = domain ? `domain:${domain}` : `org:${normalizeOrg(organization)}|${address.toLowerCase()}`;
  return {
    json: {
      Source: source,
      Organization: organization,
      Website: website,
      Domain: domain,
      'Public Phone': clean(record.publicPhone),
      'General Email': clean(record.generalEmail),
      Address: address,
      Description: description,
      'Profile URL': clean(record.profileUrl),
      'Source Page URL': clean(record.sourcePageUrl),
      'Tech Category': techCategory,
      'Tech Match': techMatch ? 'Yes' : 'No',
      'Date Scraped': clean(record.dateScraped) || new Date().toISOString(),
      'Dedup Key': dedupKey,
      'Run Notes': '',
    }
  };
});

return $input.all()
  .filter((item) => item.json['Tech Match'] === 'Yes')
  .map((item) => {
    const x = item.json;
    const row = {
      Organization: x.Organization,
      'Tech Category': x['Tech Category'],
      'Dedup Key': x['Dedup Key'],
      'Date Last Verified': x['Date Scraped'],
      'Lead Status': 'New',
      'Duplicate Review': 'Needs Review',
    };

    const copyIf = (key, value) => {
      if (value !== undefined && value !== null && String(value).trim() !== '') row[key] = value;
    };
    copyIf('Website', x.Website);
    copyIf('Public Phone', x['Public Phone']);
    copyIf('General Email', x['General Email']);
    copyIf('Address', x.Address);
    copyIf('Description', x.Description);

    if (x.Source === 'Kanata North BA') {
      row['KNBA Listed'] = 'Yes';
      row['KNBA Source URL'] = x['Profile URL'] || x['Source Page URL'];
      row['Ottawa Presence'] = 'Major Office';
    } else if (x.Source === 'Invest Ottawa') {
      row['Invest Ottawa Listed'] = 'Yes';
      row['Invest Ottawa Source URL'] = x['Profile URL'] || x['Source Page URL'];
      row['Ottawa Presence'] = 'Headquarters';
    } else if (x.Source === 'Ottawa Board of Trade') {
      row['Ottawa BOT Listed'] = 'Yes';
      row['Ottawa BOT Source URL'] = x['Profile URL'] || x['Source Page URL'];
      row['Ottawa Presence'] = 'Local Office';
    }

    return { json: row };
  });
